"use strict";(self.webpackChunk_abdm_docs_site=self.webpackChunk_abdm_docs_site||[]).push([["76575"],{92519(e,t,i){i.r(t),i.d(t,{metadata:()=>a,default:()=>l,frontMatter:()=>h,contentTitle:()=>c,toc:()=>p,assets:()=>d});var a=JSON.parse('{"id":"nhcx/v1/api/biometric/endpoints/biometric-auth-init","title":"Biometric auth init","description":"Starts a fingerprint or iris authentication of a PMJAY beneficiary against the ABHA registry and returns the txnId the verify call needs.","source":"@site/docs/nhcx/v1/api/biometric/endpoints/biometric-auth-init.mdx","sourceDirName":"nhcx/v1/api/biometric/endpoints","slug":"/nhcx/v1/api/biometric/endpoints/biometric-auth-init","permalink":"/docs/pr-12/docs/nhcx/v1/api/biometric/endpoints/biometric-auth-init","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":null,"frontMatter":{"title":"Biometric auth init","sidebar_label":"Biometric auth init","sidebar_class_name":"api-method api-method--post","description":"Starts a fingerprint or iris authentication of a PMJAY beneficiary against the ABHA registry and returns the txnId the verify call needs.","hide_table_of_contents":true,"hide_title":true,"wrapperClassName":"api-doc","verification":"unverified","source":"nhcx-biometric.yaml","generated":true},"sidebar":"nhcx-v1-api","previous":{"title":"Overview","permalink":"/docs/pr-12/docs/nhcx/v1/api/biometric/"},"next":{"title":"Biometric auth verify","permalink":"/docs/pr-12/docs/nhcx/v1/api/biometric/endpoints/biometric-auth-verify"}}'),n=i(62540),r=i(43023),s=i(44136),o=JSON.parse('{"id":"biometric_auth_init","module":"ABHA biometric authentication","moduleId":"biometric","kind":"operation","method":"POST","path":"/hcx/abha/biometric/auth/init","server":"https://apisbx.abdm.gov.in","servers":[{"url":"https://apisbx.abdm.gov.in","description":"Sandbox."}],"summary":"Biometric auth init","description":"Starts a fingerprint or iris authentication of a PMJAY beneficiary against the ABHA registry and returns the `txnId` the verify call needs.\\n\\n### Business purpose\\n\\nPMJAY requires proof that the beneficiary was physically present. A hospital proves it by authenticating them against their ABHA, biometrically, and the user token that results rides on the eligibility check, the pre-authorisation and the claim. A request without it, and without the consent form that stands in for it, is refused by name. These are ABDM calls built for the PMJAY payer, not NHCX calls: no JWE and no callbacks.\\n\\n### When to use\\n\\nAt the desk with the beneficiary present: at admission with `process` `Preauth`, and at discharge, and at every visit of a cyclic case, with `process` `Discharge`. `scope` selects the modality, `aadhaar-bio-verify` for fingerprint and `aadhaar-iris-verify` for iris. `authMode` is `FINGERPRINT` or `IRIS`. The NHCX-PMJAY-HMIS Integration Guide and the Biometric Authentication APIs Postman collection also list face on this call, `aadhaar-face-verify` with `FACE_AUTH`, but show no face request made this way; the face path documented end to end is `Face auth init` on the ABDM proxy host. `payerid` names the scheme payer the authentication is performed for.\\n\\n### Preconditions\\n\\n- The beneficiary\'s ABHA is linked to their PMJAY card. Where it is not, biometric authentication does not apply and the scheme\'s existing KYC protocols are followed.\\n- The ABDM session token on `Authorization: Bearer`, not on `bearer_auth`.\\n- `loginId` is the ABHA number with hyphens, the opposite of the envelope convention.\\n- A capture device, whose capture needs the wrapped Aadhaar data hash built with `lr` set to `Y`.\\n\\n### Postconditions\\n\\nReturns the `txnId` that `Biometric auth verify` quotes, with a message saying the authentication request was sent.\\n\\n### Common mistakes\\n\\n- Sending the token on `bearer_auth` only, which gets a `401` that looks like an expired token.\\n- Calling it on the face-authentication host. Fingerprint and iris sit under `/hcx/abha/biometric/`, face under `/pmjay/sbxhcx/abdmproxy/abha/biometric/`.\\n- Stripping the hyphens from `loginId`.\\n- Building the wrapped Aadhaar data hash with `lr` as `N`, which the biometric APIs answer with `K-547`.\\n\\n### Best practices\\n\\n- Implement fingerprint, iris and face. Each is mandatory, because any one of them may be the only one that works for a given patient.\\n- Set `process` from the stage of the case, not from a constant.\\n- Record the transaction ID, the method and the moment it succeeded against the case.\\n\\n### Related scenario\\n\\nA PMJAY beneficiary arrives for admission. The desk posts this request with `scope` `[\\"abha-login\\", \\"aadhaar-bio-verify\\"]`, `authMode` `FINGERPRINT`, the ABHA number with hyphens, `process` `Preauth` and the scheme payer\'s code, and gets a `txnId` back. The fingerprint is captured on the device and sent with that `txnId` to `Biometric auth verify`.\\n\\n### Specification\\n\\nChapter [Biometric authentication](/docs/nhcx/v1/roles/provider/biometric-authentication) of the NHCX integration specification.","security":[],"headers":[{"name":"process","required":true,"description":"No source puts `process` or `payerid` on `faceauth/init` or `capture/pid`.","example":"Preauth","type":"string"},{"name":"payerid","required":true,"description":"`payerid` is the insurer\'s own participant code. Every insurer has one, even when it works through a TPA.","example":"<payer code>","type":"string"}],"pathParams":[],"queryParams":[],"body":[{"name":"scope","type":"string[]","required":false,"description":"","encrypted":false},{"name":"loginHint","type":"string","required":false,"description":"","encrypted":false},{"name":"loginId","type":"string","required":false,"description":"","encrypted":true},{"name":"otpSystem","type":"string","required":false,"description":"","encrypted":false},{"name":"authMode","type":"string","required":false,"description":"","encrypted":false}],"requestExample":{"scope":["abha-login","aadhaar-bio-verify"],"loginHint":"abha-number","loginId":"91-XXXX-XXXX-1234","otpSystem":"aadhaar","authMode":"FINGERPRINT"},"responses":[{"status":"200","description":"Returns the `txnId` that `Biometric auth verify` quotes, with a message saying the authentication request was sent.","example":{"txnId":"8c8a12e3-xxxx-4278-xxxx-10acffa44f07","authMode":null,"message":"FingerPrint authentication request successfully sent.","status":null}}],"tag":"ABHA biometric authentication","tagDescription":"PMJAY requires proof that the beneficiary was physically present.","curl":"curl --request POST \\\\\\n  --url https://apisbx.abdm.gov.in/hcx/abha/biometric/auth/init \\\\\\n  --header \'process: Preauth\' \\\\\\n  --header \'payerid: <payer code>\' \\\\\\n  --header \'Content-Type: application/json\' \\\\\\n  --data \'{\\n  \\"scope\\": [\\n    \\"abha-login\\",\\n    \\"aadhaar-bio-verify\\"\\n  ],\\n  \\"loginHint\\": \\"abha-number\\",\\n  \\"loginId\\": \\"91-XXXX-XXXX-1234\\",\\n  \\"otpSystem\\": \\"aadhaar\\",\\n  \\"authMode\\": \\"FINGERPRINT\\"\\n}\'","samples":[{"id":"curl","label":"cURL","language":"bash","code":"curl --request POST \\\\\\n  --url https://apisbx.abdm.gov.in/hcx/abha/biometric/auth/init \\\\\\n  --header \'process: Preauth\' \\\\\\n  --header \'payerid: <payer code>\' \\\\\\n  --header \'Content-Type: application/json\' \\\\\\n  --data \'{\\n  \\"scope\\": [\\n    \\"abha-login\\",\\n    \\"aadhaar-bio-verify\\"\\n  ],\\n  \\"loginHint\\": \\"abha-number\\",\\n  \\"loginId\\": \\"91-XXXX-XXXX-1234\\",\\n  \\"otpSystem\\": \\"aadhaar\\",\\n  \\"authMode\\": \\"FINGERPRINT\\"\\n}\'"},{"id":"python","label":"Python","language":"python","code":"import requests\\n\\nresponse = requests.post(\\n    \\"https://apisbx.abdm.gov.in/hcx/abha/biometric/auth/init\\",\\n    headers={\\n        \\"process\\": \\"Preauth\\",\\n        \\"payerid\\": \\"<payer code>\\",\\n        \\"Content-Type\\": \\"application/json\\",\\n    },\\n    json={\\n        \\"scope\\": [\\n            \\"abha-login\\",\\n            \\"aadhaar-bio-verify\\"\\n        ],\\n        \\"loginHint\\": \\"abha-number\\",\\n        \\"loginId\\": \\"91-XXXX-XXXX-1234\\",\\n        \\"otpSystem\\": \\"aadhaar\\",\\n        \\"authMode\\": \\"FINGERPRINT\\"\\n    },\\n)\\n\\nprint(response.status_code, response.text)"},{"id":"node","label":"Node","language":"javascript","code":"const response = await fetch(\\"https://apisbx.abdm.gov.in/hcx/abha/biometric/auth/init\\", {\\n  method: \\"POST\\",\\n  headers: {\\n    \\"process\\": \\"Preauth\\",\\n    \\"payerid\\": \\"<payer code>\\",\\n    \\"Content-Type\\": \\"application/json\\",\\n  },\\n  body: JSON.stringify({\\n    \\"scope\\": [\\n      \\"abha-login\\",\\n      \\"aadhaar-bio-verify\\"\\n    ],\\n    \\"loginHint\\": \\"abha-number\\",\\n    \\"loginId\\": \\"91-XXXX-XXXX-1234\\",\\n    \\"otpSystem\\": \\"aadhaar\\",\\n    \\"authMode\\": \\"FINGERPRINT\\"\\n  }),\\n});\\n\\nconsole.log(response.status, await response.text());"}]}');let h={title:"Biometric auth init",sidebar_label:"Biometric auth init",sidebar_class_name:"api-method api-method--post",description:"Starts a fingerprint or iris authentication of a PMJAY beneficiary against the ABHA registry and returns the txnId the verify call needs.",hide_table_of_contents:!0,hide_title:!0,wrapperClassName:"api-doc",verification:"unverified",source:"nhcx-biometric.yaml",generated:!0},c,d={},p=[];function u(e){return(0,n.jsx)(s.A,{operation:o})}function l(e={}){let{wrapper:t}={...(0,r.R)(),...e.components};return t?(0,n.jsx)(t,{...e,children:(0,n.jsx)(u,{...e})}):u(e)}}}]);